import asyncio
from fastapi import FastAPI

async def test_startup():
    print("SYNC START")

async def test_shutdown():
    print("SYNC SHUTDOWN")

app = FastAPI(on_startup=[test_startup], on_shutdown=[test_shutdown])

async def main():
    print(f"Router Startup handlers: {app.router.on_startup}")
    print(f"Router Shutdown handlers: {app.router.on_shutdown}")

    for handler in app.router.on_startup:
        if asyncio.iscoroutinefunction(handler):
            await handler()
        else:
            handler()

    for handler in app.router.on_shutdown:
        if asyncio.iscoroutinefunction(handler):
            await handler()
        else:
            handler()

if __name__ == "__main__":
    asyncio.run(main())

